import { user } from "../authentication/schema";
import { idColumn } from "../ids";
import { sql } from "drizzle-orm";
import { check, pgTable, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";

// A desktop installation signed in as one person. The installation ID is generated by the
// desktop app and is not a credential: every request is still authorized by the session.
export const desktopDevices = pgTable(
  "desktop_devices",
  {
    id: idColumn(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    installationId: uuid("installation_id").notNull(),
    name: text("name").notNull(),
    platform: text("platform").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    unique("desktop_devices_user_installation_unique").on(table.userId, table.installationId),
    unique("desktop_devices_user_id_unique").on(table.userId, table.id),
    check("desktop_devices_name_check", sql`length(trim(${table.name})) BETWEEN 1 AND 200`),
    check("desktop_devices_platform_check", sql`length(${table.platform}) BETWEEN 1 AND 40`),
  ],
);
